<script setup lang="ts">
import {ref,computed,onMounted} from 'vue'
import {get,request} from '../api/client'
type Row=Record<string,any>
const data=ref<Row>({categories:[],labels:[],keywords:[],links:[]}),board=ref(''),label=ref(''),selected=ref<string[]>([]),error=ref(''),notice=ref(''),busy=ref(false),query=ref('')
const current=computed(()=>data.value.labels.find((r:Row)=>r.id===label.value))
const labels=computed(()=>data.value.labels.filter((r:Row)=>r.categoryId===board.value))
const keywords=computed(()=>data.value.keywords.filter((r:Row)=>(r.status==='ENABLED'||selected.value.includes(r.id))&&r.name.includes(query.value)))
function choose(id:string){label.value=id;selected.value=data.value.links.filter((r:Row)=>r.labelId===id).map((r:Row)=>r.keywordId);notice.value=''}
async function load(){data.value=await get('/api/v1/admin/catalog/curation');if(!board.value)board.value=data.value.categories[0]?.id||'';if(label.value)choose(label.value)}
async function save(){busy.value=true;error.value='';try{await request('PUT','/api/v1/admin/catalog/labels/'+label.value+'/keywords',{keywordIds:selected.value,expectedVersion:current.value.lockVersion});await load();notice.value='编排已保存'}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
function ancestry(row:Row){const names:string[]=[];const seen=new Set<string>();let p=row.parentId;while(p&&!seen.has(p)){seen.add(p);const parent=data.value.labels.find((r:Row)=>r.id===p);if(!parent)break;names.unshift(parent.name);p=parent.parentId}return names.join(' / ')}
onMounted(async()=>{try{await load()}catch(e){error.value=(e as Error).message}})
</script>
<template><section><div class="title-row"><div><h1>板块 · 标签 · 关键词</h1><p class="muted">按内容结构维护入口，同一个关键词可编排到多个标签。</p></div><router-link to="/categories/new">新增板块</router-link></div><p class="error" role="alert">{{ error }}</p><p role="status">{{ notice }}</p><div class="catalog-grid"><div class="panel"><h2>板块</h2><button v-for="r in data.categories" :key="r.id" class="tree-row" :class="{selected:board===r.id}" @click="board=r.id;label=''">{{ r.name }} <small>{{ r.status==='DISABLED'?'已停用':'' }}</small></button><router-link v-if="board" :to="'/categories/'+board+'/edit'">编辑当前板块</router-link></div><div class="panel"><h2>标签</h2><button v-for="r in labels" :key="r.id" class="tree-row" :class="{selected:label===r.id}" @click="choose(r.id)"><small v-if="ancestry(r)">{{ ancestry(r) }} / </small>{{ r.name }}</button><p v-if="!labels.length" class="muted">该板块暂无标签</p><router-link to="/labels/new">新增标签</router-link></div><div class="panel"><template v-if="current"><h2>{{ current.name }} · 关键词</h2><router-link :to="'/labels/'+current.id+'/edit'">编辑标签属性</router-link><label>查找关键词<input v-model="query" placeholder="输入名称"/></label><div class="keyword-options"><label v-for="k in keywords" :key="k.id" class="check-row"><input v-model="selected" type="checkbox" :value="k.id"/>{{ k.name }}{{ k.status==='DISABLED'?'（已停用，请取消勾选）':'' }}</label></div><p>已选择 {{ selected.length }} 个</p><button :disabled="busy" @click="save">保存关键词编排</button></template><p v-else class="empty">选择标签后维护关键词</p><p><router-link to="/keywords/new">新增关键词</router-link> · <router-link to="/keywords">关键词治理</router-link></p></div></div></section></template>
<style scoped>.catalog-grid{display:grid;grid-template-columns:1fr 1fr 1.5fr;gap:16px}.tree-row{display:block;width:100%;background:transparent;color:#264a45;text-align:left;margin:4px 0}.tree-row.selected{background:#deeee8}.tree-row small{display:block;color:#607b73}.check-row{display:flex;flex-direction:row;align-items:center;gap:8px;font-weight:400}.keyword-options{max-height:420px;overflow:auto}@media(max-width:1000px){.catalog-grid{grid-template-columns:1fr}}</style>
